"""Chapter 8: Addition Reactions of Alkenes (50 multiple choice + 50 free response)."""
from qb import *
from rdkit import Chem
from rdkit.Chem import AllChem
import numpy as np


def build(b):
    CIS_DIBR = 'Br[C@@H]1CCCC[C@@H]1Br'
    TRANS_DIBR = 'Br[C@@H]1CCCC[C@H]1Br'
    CIS_DIOL = 'O[C@@H]1CCCC[C@@H]1O'
    TRANS_DIOL = 'O[C@@H]1CCCC[C@H]1O'
    CIS_ME = 'C[C@@H]1CCCC[C@@H]1C'
    TRANS_MEOH = 'C[C@@H]1CCCC[C@H]1O'
    # a symmetric 1,2-disubstituted ring is meso (labels R,S) only when cis; the same atom order keeps that meaning for other groups
    for cis_, trans_ in [(CIS_DIBR, TRANS_DIBR), (CIS_DIOL, TRANS_DIOL)]:
        assert sorted(cip(cis_)) == ['R', 'S'] and cip(trans_)[0] == cip(trans_)[1]
    # ------------------------------------------------------------ 8.1 - 8.4
    b.mc('8.1', 1, 'In an addition reaction to an alkene, what happens?', 'Two groups add across the double bond and the π bond is lost', ['A leaving group is replaced', 'A proton and a leaving group are lost', 'The σ bond is broken'], 'The π bond breaks and two new σ bonds form.')
    b.mc('8.2', 1, 'Which small alkene is the largest-volume starting material of the chemical industry?', 'Ethylene', ['Methane', 'Benzene', 'Acetylene'], 'Ethylene is made by cracking petroleum.')
    b.mc('8.3', 1, 'What is the degree of substitution of the double bond in 2-methylbut-2-ene?', 'Trisubstituted', ['Monosubstituted', 'Disubstituted', 'Tetrasubstituted'], 'Three alkyl groups are attached to the double bond carbons.', img=S('CC=C(C)C'))
    b.mc('8.3', 2, 'What is the degree of substitution of the double bond in 2,3-dimethylbut-2-ene?', 'Tetrasubstituted', ['Trisubstituted', 'Disubstituted', 'Monosubstituted'], 'Four alkyl groups are attached to the alkene carbons.', img=S('CC(C)=C(C)C'))
    b.mcname('8.3', 2, 'What is the IUPAC name of the alkene shown?', 'CC=C(C)C', ['3-methylbut-1-ene', '2-methylbut-3-ene', '2-methylbut-1-ene'], 'Number to give the double bond the lowest locant, then name the substituent.')
    b.mc('8.4', 3, 'Why are addition reactions disfavored at high temperature?', 'ΔS is negative, so −TΔS opposes the reaction at high T', ['ΔH is positive', 'The π bond becomes stronger', 'The reaction is always exothermic'], 'Two molecules become one, so entropy decreases.')
    # ------------------------------------------------------------ 8.5 Hydrohalogenation
    b.mcstruct('8.5', 2, 'What is the major product of the reaction of propene with HBr?', 'CC(C)Br', ['CCCBr', 'CC(Br)CBr', 'CCC'], 'Markovnikov addition puts Br on the more substituted carbon.')
    b.mc('8.5', 1, 'Markovnikov addition of HX puts the halogen on:', 'The more substituted carbon of the double bond', ['The less substituted carbon', 'A carbon next to the double bond', 'Both carbons'], 'The more stable carbocation forms first.')
    b.mc('8.5', 2, 'What is the intermediate in the addition of HBr to an alkene?', 'A carbocation', ['A carbanion', 'A radical', 'A bromonium ion'], 'Protonation of the alkene gives a carbocation, which Br⁻ then attacks.')
    b.mcstruct('8.5', 3, 'What is the major product when 2-methylpropene reacts with HBr?', 'CC(C)(C)Br', ['CC(C)CBr', 'CC(C)C', 'C=C(C)C'], 'The tertiary carbocation is the intermediate.')
    b.mcstruct('8.5', 3, 'What is the major product when propene reacts with HBr in the presence of peroxides (ROOR)?', 'CCCBr', ['CC(C)Br', 'CC(Br)CBr', 'CCC'], 'Peroxides lead to a radical mechanism and anti-Markovnikov addition.')
    b.mc('8.5', 3, 'The addition of HBr to 3-methylbut-1-ene gives mainly 2-bromo-2-methylbutane. This is because:', 'A hydride shift converts a secondary carbocation to a tertiary one', ['HBr adds in an anti-Markovnikov sense', 'A radical intermediate forms', 'The alkene rearranges before protonation'], 'A carbocation rearrangement gives the more stable cation.', img=S('C=CC(C)C'))
    b.mc('8.5', 3, 'Adding HCl to 1-methylcyclohexene gives a product with how many stereoisomers?', 'One (the product has no chirality center)', ['Two', 'Four', 'Three'], 'The tertiary chloride is achiral because the ring is symmetric.', img=S('CC1=CCCCC1'))
    b.mc('8.5', 4, 'Hydrohalogenation of but-1-ene gives 2-bromobutane. What is the stereochemical result?', 'A racemic mixture', ['Only the R enantiomer', 'Only the S enantiomer', 'A meso compound'], 'The planar carbocation is attacked from either face.', img=S('C=CCC'))
    # ------------------------------------------------------------ 8.6 / 8.7 Hydration
    b.mcstruct('8.6', 2, 'What is the major product when 2-methylpropene is treated with H₂O and H₂SO₄?', 'CC(C)(C)O', ['CC(C)CO', 'CC(C)C', 'CC(C)(C)OC(C)(C)C'], 'Markovnikov hydration gives the tertiary alcohol.')
    b.mc('8.6', 2, 'Which reaction conditions give an alkene from an alcohol?', 'Concentrated acid and heat', ['Dilute acid at room temperature', 'NaOH', 'H₂, Pt'], 'Concentrated acid favors elimination; dilute acid favors hydration.')
    b.mc('8.6', 3, 'Why is acid-catalyzed hydration of 3-methylbut-1-ene a poor way to make 3-methylbutan-2-ol?', 'A carbocation rearrangement gives a different alcohol', ['The alkene is unreactive', 'Water is a poor nucleophile', 'Anti-Markovnikov addition occurs'], 'The secondary cation rearranges to a tertiary cation.', img=S('C=CC(C)C'))
    b.mc('8.7', 1, 'Oxymercuration-demercuration is the addition of:', 'H and OH across a double bond without carbocation rearrangements', ['H and Br across a double bond', 'Two OH groups to the same face', 'H₂ across a double bond'], 'The mercurinium ion prevents rearrangement.')
    b.mcstruct('8.7', 3, 'What is the product of 3-methylbut-1-ene with (1) Hg(OAc)₂, H₂O; (2) NaBH₄?', 'CC(C)C(C)O', ['CC(C)CCO', 'CCC(C)(C)O', 'CC(C)C=C'], 'Markovnikov hydration without rearrangement gives the secondary alcohol.')
    # ------------------------------------------------------------ 8.8 Hydroboration
    b.mcstruct('8.8', 2, 'What is the major product of propene with (1) BH₃·THF; (2) H₂O₂, NaOH?', 'CCCO', ['CC(C)O', 'CC(O)CO', 'CCC'], 'Hydroboration-oxidation gives anti-Markovnikov hydration.')
    b.mc('8.8', 2, 'Hydroboration-oxidation proceeds with which stereochemistry?', 'Syn addition of H and OH', ['Anti addition of H and OH', 'Both syn and anti equally', 'Radical addition'], 'H and B add to the same face in a concerted step.')
    b.mc('8.8', 3, 'Hydroboration-oxidation of 1-methylcyclohexene gives which product?', 'trans-2-Methylcyclohexan-1-ol', ['cis-2-Methylcyclohexan-1-ol', '1-Methylcyclohexan-1-ol', '2-Methylcyclohexene'], 'OH goes to the less substituted carbon and syn addition of H and OH places H and OH on the same face, leaving CH₃ and OH trans.', img=S('CC1=CCCCC1'))
    b.mc('8.8', 3, 'Which statement about BH₃ addition is correct?', 'Boron attaches to the less hindered carbon and H adds to the more substituted carbon', ['Boron attaches to the more substituted carbon', 'A carbocation is formed', 'The reaction is stepwise'], 'The addition is concerted with boron on the less substituted carbon.')
    # ------------------------------------------------------------ 8.9 Hydrogenation
    b.mc('8.9', 1, 'Which reagents hydrogenate an alkene?', 'H₂ with Pt, Pd or Ni', ['H₂O and H₂SO₄', 'BH₃ then H₂O₂', 'O₃ then DMS'], 'A metal catalyst is required.')
    b.mc('8.9', 2, 'Catalytic hydrogenation proceeds with:', 'Syn addition of H₂', ['Anti addition of H₂', 'Markovnikov addition', 'Radical addition'], 'Both H atoms are delivered from the catalyst surface to the same face.')
    b.mc('8.9', 3, 'Which product is formed when 1,2-dimethylcyclohexene is hydrogenated with H₂, Pt?', 'cis-1,2-Dimethylcyclohexane', ['trans-1,2-Dimethylcyclohexane', '1,1-Dimethylcyclohexane', 'Methylcyclohexane'], 'Syn addition of H₂ puts both methyl groups on the same face.', img=S('CC1=C(C)CCCC1'))
    b.mc('8.9', 2, 'A homogeneous catalyst is one that:', 'Is soluble in the reaction mixture', ['Is a solid not soluble in the solvent', 'Is not used up', 'Is always chiral'], 'Homogeneous means the same phase as the reactants.')
    # ------------------------------------------------------------ 8.10 Halogenation
    b.mc('8.10', 1, 'What is the intermediate in the bromination of an alkene with Br₂?', 'A bromonium ion', ['A carbocation', 'A carbanion', 'A radical'], 'A bridged three-membered ring forms.')
    b.mcstruct('8.10', 3, 'What is the product of cyclohexene with Br₂ in CH₂Cl₂?', TRANS_DIBR, [CIS_DIBR, 'BrC1CCCCC1', 'BrC1(Br)CCCCC1'], 'The bromonium ion is opened from the opposite face, so the addition is anti.')
    b.mc('8.10', 2, 'The addition of Br₂ to an alkene is:', 'Anti', ['Syn', 'Markovnikov', 'Radical only'], 'The bromide attacks the bromonium ion from the side opposite the Br bridge.')
    b.mcstruct('8.10', 3, 'What is the major product when 1-methylcyclohexene is treated with Br₂ in water?', 'CC1(O)CCCCC1Br', ['C[C@]1(Br)CCCC[C@@H]1O', 'CC1(Br)CCCCC1Br', 'CC1(O)CCCCC1O'], 'Water attacks the more substituted carbon (the one that bears more positive charge) and the bromine ends up on the neighbouring carbon.') if False else None
    b.mc('8.10', 3, 'When Br₂ is added to an alkene in water, where does OH end up?', 'On the more substituted carbon', ['On the less substituted carbon', 'On both carbons', 'It does not add'], 'The more substituted carbon of the bromonium ion carries more positive charge.')
    b.mc('8.10', 3, 'What is the product of Br₂ and H₂O with propene?', '1-Bromopropan-2-ol', ['2-Bromopropan-1-ol', '1,2-Dibromopropane', 'Propane-1,2-diol'], 'OH adds to the more substituted carbon; Br adds to the terminal carbon.', img=R('C=CC', None, top=['Br₂, H₂O'], bottom=[]))
    # ------------------------------------------------------------ 8.11 / 8.12 Dihydroxylation
    b.mcstruct('8.11', 3, 'What is the product of cyclohexene with (1) mCPBA; (2) H₃O⁺?', TRANS_DIOL, [CIS_DIOL, 'OC1CCCCC1', 'O=C1CCCCC1'], 'Epoxidation followed by acid-catalyzed opening gives anti dihydroxylation.')
    b.mcstruct('8.12', 3, 'What is the product of cyclohexene with OsO₄ then NaHSO₃/H₂O?', CIS_DIOL, [TRANS_DIOL, 'OC1CCCCC1', 'O=C1CCCCC1'], 'OsO₄ adds both oxygens to the same face: syn dihydroxylation.')
    b.mc('8.12', 1, 'Which reagent can convert an alkene to a syn diol?', 'OsO₄', ['O₃', 'mCPBA, then H₃O⁺', 'HBr'], 'OsO₄ (or cold, dilute KMnO₄) gives syn dihydroxylation.')
    b.mc('8.11', 2, 'What is formed first from an alkene and mCPBA?', 'An epoxide', ['A diol', 'A carbocation', 'An alkyl halide'], 'The peroxy acid transfers an oxygen atom to the alkene.')
    # ------------------------------------------------------------ 8.13 Ozonolysis
    b.mc('8.13', 1, 'Ozonolysis of an alkene followed by DMS cleaves the double bond to give:', 'Two carbonyl compounds', ['Two alcohols', 'An epoxide', 'A diol'], 'Each alkene carbon becomes a C=O.')
    b.mcstruct('8.13', 3, 'Which compounds form from 2-methylbut-2-ene with (1) O₃; (2) DMS?', 'CC=O.CC(C)=O', ['CC(=O)O.CC(C)=O', 'CC(O)C(C)(C)O', 'CC(C)=O.CCO'], 'Cleavage of the double bond gives acetaldehyde and acetone.')
    b.mc('8.13', 3, 'Ozonolysis of cyclohexene (O₃ then DMS) gives:', 'Hexanedial', ['Cyclohexane-1,2-diol', 'Two molecules of ethanal', 'Cyclohexanone'], 'The ring is opened to a dialdehyde.', img=S('C1=CCCCC1'))
    b.mc('8.13', 4, 'Which alkene gives a single product (propanal) when treated with O₃ then DMS?', 'Hex-3-ene', ['Hex-1-ene', 'Hex-2-ene', '2-Methylhex-2-ene'], 'A symmetrical alkene gives two identical carbonyl compounds.')
    # ------------------------------------------------------------ 8.14 / 8.15 Predicting and synthesis
    b.mc('8.14', 2, 'Which reagent adds H and OH to an alkene with anti-Markovnikov regiochemistry?', 'BH₃·THF, then H₂O₂, NaOH', ['H₂O, H₂SO₄', 'Hg(OAc)₂, H₂O then NaBH₄', 'OsO₄'], 'Hydroboration-oxidation gives the anti-Markovnikov alcohol.')
    b.mc('8.14', 3, 'Which of these does NOT proceed through a carbocation intermediate?', 'Hydroboration-oxidation', ['HBr addition (no peroxides)', 'Acid-catalyzed hydration', 'Hydrochlorination'], 'Hydroboration is concerted.')
    b.mc('8.14', 3, 'What three questions help you predict an addition product?', 'Which groups add, regiochemistry and stereochemistry', ['Solvent, temperature and pressure', 'Number of carbons, rings and π bonds', 'Rate, yield and cost'], 'These are the questions listed in Klein section 8.14.')
    b.mc('8.15', 2, 'What sequence converts 1-bromopropane into 2-bromopropane?', '(1) NaOEt, heat; (2) HBr', ['(1) HBr; (2) NaOEt', '(1) H₂, Pt; (2) HBr', '(1) O₃; (2) DMS'], 'Eliminate to propene, then add HBr in a Markovnikov sense.')
    b.mc('8.15', 3, 'To convert cyclohexene into cis-cyclohexane-1,2-diol, use:', 'OsO₄ then NaHSO₃', ['mCPBA then H₃O⁺', 'Br₂ then NaOH', 'BH₃ then H₂O₂'], 'Syn dihydroxylation.')
    b.mc('8.15', 4, 'To convert 1-methylcyclohexene to 2-methylcyclohexan-1-ol (trans), use:', 'BH₃·THF; then H₂O₂, NaOH', ['H₂O, H₂SO₄', 'HBr then NaOH', 'Hg(OAc)₂, H₂O; then NaBH₄'], 'Anti-Markovnikov hydration (syn addition).', img=S('CC1=CCCCC1'))
    b.mc('8.15', 4, 'To convert 2-bromo-2-methylpropane into 2-methylpropan-1-ol, a good route is:', '(1) t-BuOK; (2) BH₃·THF; (3) H₂O₂, NaOH', ['(1) NaOH', '(1) H₂O, heat', '(1) HBr; (2) NaOH'], 'Eliminate to the alkene, then add water anti-Markovnikov.')
    b.mc('8.3', 1, 'How many carbon atoms are in the longest chain containing the double bond of 2-methylbut-2-ene?', '4', ['3', '5', '2'], 'But- means four carbons; the methyl is a substituent.', img=S('CC=C(C)C'))
    b.mc('8.5', 2, 'In the addition of HBr to an alkene, which species acts as the electrophile in the first step?', 'H⁺ (the proton of HBr)', ['Br⁻', 'The alkene carbon', 'The carbocation'], 'The π bond attacks the proton of HBr.')
    b.mc('8.9', 2, 'What is the product of 2-methylpropene with H₂, Pt?', 'Isobutane (2-methylpropane)', ['Butane', '2-Methylpropan-2-ol', '2-Bromo-2-methylpropane'], 'Hydrogenation converts C=C to C-C.', img=S('C=C(C)C'))
    # ================================================================ free response
    b.fr('8.1', 1, 'Define an addition reaction and give an example.', 'Two groups add across a double bond; for example CH₂=CH₂ + HBr → CH₃CH₂Br.', 'The π bond is converted into two σ bonds.')
    b.fr('8.1', 2, 'What kind of bond is broken and what is formed in an addition to an alkene?', 'The π bond is broken and two new σ bonds are formed.', 'π to two σ.')
    b.fr('8.2', 1, 'Name two alkenes produced industrially by cracking petroleum.', 'Ethylene (ethene) and propylene (propene).', 'Smallest alkenes.')
    b.fr('8.3', 2, 'Classify the double bond of 2-methylbut-2-ene as mono-, di-, tri- or tetrasubstituted.', 'Trisubstituted: three alkyl groups are on the double bond carbons.', 'Count the alkyl groups on the double bond.', img=S('CC=C(C)C'))
    b.fr('8.3', 2, 'Draw 3-methylcyclohexene.', 'A six-membered ring with a double bond between C1 and C2 and a methyl group on C3.', 'The double bond gets locants 1 and 2.', aimg=S('CC1C=CCCC1'))
    b.fr('8.3', 3, 'Name the compound shown, giving its E/Z descriptor.', '(E)-3-Methylpent-2-ene', 'Rank the groups on each alkene carbon.', img=S('C/C=C(C)/CC'))
    b.fr('8.4', 2, 'Explain why alkene hydrogenation is thermodynamically favorable at room temperature.', 'A weak π bond and an H-H bond are converted into two stronger C-H σ bonds, so ΔH is strongly negative.', 'Bond energies.')
    b.fr('8.4', 3, 'Explain why elimination becomes more favorable relative to addition as temperature increases.', 'Elimination increases the number of molecules (ΔS > 0), so the −TΔS term makes ΔG more negative at high temperature.', 'Entropy.')
    b.fr('8.5', 2, 'Draw the major product of 2-methylbut-2-ene with HCl.', '2-Chloro-2-methylbutane (tertiary chloride).', 'Markovnikov.', img=R('CC=C(C)C', None, top=['HCl'], bottom=[]), aimg=S('CCC(C)(C)Cl'))
    b.fr('8.5', 2, 'Draw the major product of propene with HBr in the presence of peroxides and state the regiochemistry.', '1-Bromopropane; anti-Markovnikov addition (radical mechanism).', 'Peroxides change the mechanism.', img=R('C=CC', None, top=['HBr, ROOR'], bottom=[]), aimg=S('CCCBr'))
    b.fr('8.5', 3, 'Explain why HBr adds to propene to give 2-bromopropane rather than 1-bromopropane.', 'Protonation at the terminal carbon gives a secondary carbocation, more stable than the primary cation from the other orientation; Br⁻ then attacks the secondary carbocation.', 'Stability of the intermediate decides.')
    b.fr('8.5', 3, 'Show the first step of the mechanism of HBr with propene using curved arrows.', 'One arrow from the π bond to the H of HBr and one from the H-Br bond to Br, giving a secondary carbocation and Br⁻.', 'Two arrows.', aimg=A('[H:5][Br:6].[CH2:1]=[CH:2]C', [(('bond', 1, 2), ('atom', 5), {'bend': .5}), (('bondf', 5, 6, .3), ('atom', 6), {'bend': .6, 'e_off': -9})]))
    b.fr('8.5', 3, 'Predict the product of 3,3-dimethylbut-1-ene with HCl and explain why it is not the direct Markovnikov product.', '2-Chloro-2,3-dimethylbutane: the secondary carbocation rearranges by a methyl shift to a tertiary carbocation before chloride attacks.', 'Look for a rearrangement.', img=S('C=CC(C)(C)C'), aimg=S('CC(C)C(C)(C)Cl'))
    b.fr('8.5', 4, 'When HBr adds to but-1-ene, how many stereoisomers are formed, and in what ratio?', 'Two: the R and S enantiomers of 2-bromobutane in a 1:1 (racemic) ratio, because the planar carbocation is attacked equally from both faces.', 'Planar intermediate.', img=S('C=CCC'))
    b.fr('8.6', 1, 'What reagents add water to an alkene with Markovnikov regiochemistry?', 'H₂O with H₂SO₄ or H₃O⁺ (acid-catalyzed hydration).', 'Aqueous acid.')
    b.fr('8.6', 2, 'Draw the product of 1-methylcyclohexene with H₂O, H₂SO₄.', '1-Methylcyclohexan-1-ol.', 'Markovnikov: OH on the more substituted carbon.', img=R('CC1=CCCCC1', None, top=['H₂O, H₂SO₄'], bottom=[]), aimg=S('CC1(O)CCCCC1'))
    b.fr('8.6', 3, 'Describe the three steps of the mechanism of acid-catalyzed hydration of propene.', '1) Protonation of the alkene gives a secondary carbocation. 2) Water attacks the carbocation, giving an oxonium ion. 3) Deprotonation by water gives propan-2-ol.', 'Protonate, attack, deprotonate.')
    b.fr('8.6', 3, 'How do you favor the alkene when converting an alcohol to an alkene and the alcohol when hydrating an alkene?', 'Use concentrated acid and heat to favor the alkene; dilute acid (excess water) to favor the alcohol.', 'Le Chatelier.')
    b.fr('8.7', 2, 'What advantage does oxymercuration-demercuration have over acid-catalyzed hydration?', 'It does not involve a free carbocation, so no rearrangement occurs.', 'The mercurinium ion.')
    b.fr('8.7', 3, 'Draw the product of 3-methylbut-1-ene with (1) Hg(OAc)₂, H₂O; (2) NaBH₄.', '3-Methylbutan-2-ol (Markovnikov, no rearrangement).', 'No carbocation rearrangement.', img=S('C=CC(C)C'), aimg=S('CC(C)C(C)O'))
    b.fr('8.8', 1, 'What reagents add H and OH to an alkene with anti-Markovnikov regiochemistry?', '(1) BH₃·THF; (2) H₂O₂, NaOH.', 'Hydroboration-oxidation.')
    b.fr('8.8', 2, 'Draw the product of 2-methylpropene with (1) BH₃·THF; (2) H₂O₂, NaOH.', '2-Methylpropan-1-ol.', 'OH goes to the less substituted carbon.', img=S('C=C(C)C'), aimg=S('CC(C)CO'))
    b.fr('8.8', 3, 'Explain the stereochemical outcome of hydroboration-oxidation of 1-methylcyclohexene.', 'H and OH add to the same face (syn), so the product is trans-2-methylcyclohexan-1-ol (CH₃ and OH trans), formed as a racemate.', 'Syn addition of H and B.', img=S('CC1=CCCCC1'), aimg=S(TRANS_MEOH))
    b.fr('8.8', 3, 'Why is no carbocation rearrangement observed in hydroboration?', 'The reaction is concerted: no carbocation is formed, so there is nothing to rearrange.', 'One step, no cation.')
    b.fr('8.9', 1, 'What reagents are needed to hydrogenate an alkene?', 'H₂ and a metal catalyst (Pd, Pt or Ni).', 'Heterogeneous catalysts.')
    b.fr('8.9', 2, 'Draw the product of 1,2-dimethylcyclohexene with H₂, Pt and state the stereochemistry.', 'cis-1,2-Dimethylcyclohexane, because both H atoms add to the same face (syn).', 'Syn addition.', img=S('CC1=C(C)CCCC1'), aimg=S(CIS_ME))
    b.fr('8.9', 3, 'Explain the difference between a homogeneous and a heterogeneous catalyst.', 'A homogeneous catalyst dissolves in the reaction mixture; a heterogeneous catalyst is a solid that does not (for example Pd/C).', 'Phases.')
    b.fr('8.10', 2, 'Draw the product of cyclohexene with Br₂ and state the stereochemistry.', 'trans-1,2-Dibromocyclohexane (as a racemate), from anti addition.', 'Anti addition via a bromonium ion.', img=R('C1=CCCCC1', None, top=['Br₂'], bottom=[]), aimg=S(TRANS_DIBR))
    b.fr('8.10', 3, 'Explain why bromination of an alkene gives anti addition.', 'The alkene forms a bridged bromonium ion; bromide must attack from the side opposite the bridge (SN2-like), so the two Br atoms end up on opposite faces.', 'Back-side attack on a three-membered ring.')
    b.fr('8.10', 3, 'Draw the product of propene with Br₂ in water and name it.', '1-Bromopropan-2-ol; OH adds to the more substituted carbon.', 'Halohydrin formation.', img=R('C=CC', None, top=['Br₂, H₂O'], bottom=[]), aimg=S('CC(O)CBr'))
    b.fr('8.10', 4, 'Explain why water attacks the more substituted carbon of the bromonium ion in halohydrin formation.', 'The more substituted carbon bears a larger partial positive charge because it better stabilizes the charge, so the nucleophile attacks it.', 'Partial carbocation character.')
    b.fr('8.11', 2, 'Draw the product of cyclohexene with (1) mCPBA; (2) H₃O⁺.', 'trans-Cyclohexane-1,2-diol (anti dihydroxylation).', 'Epoxide, then ring opening.', img=S('C1=CCCCC1'), aimg=S(TRANS_DIOL))
    b.fr('8.12', 2, 'Draw the product of cyclohexene with OsO₄, then NaHSO₃/H₂O.', 'cis-Cyclohexane-1,2-diol (syn dihydroxylation).', 'Both OH groups add to the same face.', img=S('C1=CCCCC1'), aimg=S(CIS_DIOL))
    b.fr('8.12', 3, 'Compare how to make cis and trans cyclohexane-1,2-diol from cyclohexene.', 'cis: OsO₄ (or cold, dilute KMnO₄) in a syn addition. trans: mCPBA followed by H₃O⁺ (epoxide opening, anti addition).', 'Syn vs anti.')
    b.fr('8.13', 1, 'What two carbon-containing groups does ozonolysis (O₃; DMS) produce from an alkene?', 'Two carbonyl groups (aldehydes and/or ketones).', 'The double bond is cleaved.')
    b.fr('8.13', 2, 'Draw the products of 2-methylbut-2-ene with (1) O₃; (2) DMS.', 'Acetone and acetaldehyde.', 'Each alkene carbon becomes a C=O.', img=S('CC=C(C)C'), aimg=S('CC(C)=O', 'CC=O'))
    b.fr('8.13', 3, 'An alkene gives only one product, acetone, on ozonolysis with DMS workup. Identify the alkene.', '2,3-Dimethylbut-2-ene.', 'Two identical halves.', aimg=S('CC(C)=C(C)C'))
    b.fr('8.13', 3, 'Draw the product of cyclopentene with (1) O₃; (2) DMS.', 'Pentanedial (glutaraldehyde), OHC-CH₂CH₂CH₂-CHO.', 'The ring is cleaved.', img=S('C1=CCC1') if False else S('C1=CCCC1'), aimg=S('O=CCCCC=O'))
    b.fr('8.14', 2, 'List the three questions used to predict the product of an addition reaction.', 'Which groups are added, what regiochemistry (Markovnikov or anti-Markovnikov), and what stereochemistry (syn or anti).', 'Klein 8.14.')
    b.fr('8.14', 3, 'Which reagent would you use to convert 1-methylcyclohexene to 1-methylcyclohexan-1-ol and which to 2-methylcyclohexan-1-ol?', 'H₂O, H₂SO₄ (or oxymercuration) for the 1-ol (Markovnikov); BH₃ then H₂O₂, NaOH for the 2-ol (anti-Markovnikov).', 'Choose by regiochemistry.', img=S('CC1=CCCCC1'))
    b.fr('8.14', 3, 'Draw the product of propene with (1) BH₃·THF; (2) H₂O₂, NaOH and the product of propene with H₂O, H₂SO₄. How are they related?', 'Propan-1-ol and propan-2-ol, which are constitutional (regio) isomers.', 'Opposite regiochemistry.', aimg=S('CCCO', 'CC(C)O', labels='1° 2°') if False else S('CCCO', 'CC(C)O'))
    b.fr('8.14', 4, 'Design reagents to convert 1-methylcyclohexene into trans-2-methylcyclohexan-1-ol and explain each feature of the outcome.', 'BH₃·THF then H₂O₂, NaOH: anti-Markovnikov (OH on the less substituted carbon) and syn addition of H and OH, so CH₃ and OH end up trans.', 'Hydroboration-oxidation.', img=S('CC1=CCCCC1'), aimg=S(TRANS_MEOH))
    b.fr('8.15', 2, 'How can you change the position of a halogen using elimination and addition?', 'Eliminate HX to form an alkene (E2), then add HX in the desired orientation (Markovnikov or anti-Markovnikov with peroxides).', 'Eliminate then add.')
    b.fr('8.15', 3, 'Propose a synthesis of 1-bromopropane from 2-bromopropane.', '(1) NaOEt, heat (E2) to give propene; (2) HBr, ROOR (anti-Markovnikov).', 'Eliminate, then radical addition.', img=S('CC(C)Br'), aimg=S('CCCBr'))
    b.fr('8.15', 3, 'Propose a synthesis of cis-cyclohexane-1,2-diol from cyclohexanol.', '(1) H₂SO₄, heat (dehydration) to cyclohexene; (2) OsO₄, then NaHSO₃.', 'Eliminate, then syn dihydroxylation.', img=S('OC1CCCCC1'), aimg=S(CIS_DIOL))
    b.fr('8.15', 4, 'Propose a synthesis of 2-methylpropan-1-ol from 2-methylpropan-2-ol.', '(1) H₂SO₄, heat to give 2-methylpropene; (2) BH₃·THF; (3) H₂O₂, NaOH.', 'Dehydrate, then hydroboration-oxidation.', img=S('CC(C)(C)O'), aimg=S('CC(C)CO'))
    b.fr('8.15', 4, 'Propose a synthesis of acetone and formaldehyde from 2-methylpropene.', 'Treat 2-methylpropene with (1) O₃; (2) DMS.', 'Ozonolysis splits the double bond.', img=S('C=C(C)C'), aimg=S('CC(C)=O', 'C=O'))
    b.fr('8.5', 2, 'Why does HBr add to an alkene faster than HCl typically?', 'HBr is the stronger acid, so protonating the π bond is easier.', 'Compare acidities of the hydrogen halides.')
    b.fr('8.9', 2, 'Draw the product of 2-methylpropene with H₂, Pt.', '2-Methylpropane.', 'The double bond becomes a single bond.', img=S('C=C(C)C'), aimg=S('CC(C)C'))
    b.fr('8.12', 2, 'Why does syn dihydroxylation with OsO₄ give only the cis diol from cyclohexene?', 'The two oxygens are delivered together from OsO₄ to the same face of the double bond in a cyclic osmate ester.', 'A cyclic intermediate delivers both oxygens at once.')
